import functools
from typing import ForwardRef, Any, Callable
from fastapi.dependencies.utils import get_typed_signature
import inspect

class B:
    pass

def wrapper(func: Callable[..., Any]) -> Callable[..., Any]:
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def my_func(x: "B"):
    pass

wrapped_func = wrapper(my_func)

def test_wrapped_func_forward_ref():
    try:
        sig = get_typed_signature(wrapped_func)
        print("Signature obtained successfully")
        # Check if the annotation was resolved to B
        param = sig.parameters['x']
        print(f"Annotation: {param.annotation}")
        assert param.annotation is B
    except NameError as e:
        print(f"Caught NameError: {e}")
        raise e

if __name__ == "__main__":
    test_wrapped_func_forward_ref()
